using namespace std;
typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);
    vector<ll> s(n), d(n), v(n);
    for (auto &x : s) scanf("%lld", &x);
    for (auto &x : d) scanf("%lld", &x);
    for (auto &x : v) scanf("%lld", &x);
    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return s[x] + d[x] < s[y] + d[y]; });
    vector<ll> ends(n), best(n + 1, 0);
    for (int i = 0; i < n; i++) ends[i] = s[ord[i]] + d[ord[i]];
    for (int i = 1; i <= n; i++) {
        int c = ord[i - 1];
        // Calls ending no later than this start can precede it (half-open intervals).
        int p = upper_bound(ends.begin(), ends.begin() + (i - 1), s[c]) - ends.begin();
