}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] s = new long[n], e = new long[n], v = new long[n];
        for (int i = 0; i < n; i++) s[i] = nextLong();
        for (int i = 0; i < n; i++) e[i] = s[i] + nextLong();
        for (int i = 0; i < n; i++) v[i] = nextLong();
        // Sort indices by end time: pack (end, index) into one long.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = e[i] << 17 | i;
        Arrays.sort(key);
        long[] ends = new long[n], best = new long[n + 1];
        int[] ord = new int[n];
        for (int i = 0; i < n; i++) {
            ord[i] = (int) (key[i] & ((1 << 17) - 1));
            ends[i] = e[ord[i]];
        }
        for (int i = 1; i <= n; i++) {
            int c = ord[i - 1];
            // Count calls among the first i-1 ending no later than this start (half-open intervals).
            int lo = 0, hi = i - 1;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] <= s[c]) lo = mid + 1;
                else hi = mid;
            }
            best[i] = Math.max(best[i - 1], best[lo] + v[c]);
        }
        System.out.println(best[n]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	s := make([]int64, n)
	e := make([]int64, n)
	v := make([]int64, n)
	for i := range s {
		s[i] = nextInt()
	}
	for i := range e {
		e[i] = s[i] + nextInt()
	}
	for i := range v {
		v[i] = nextInt()
	}
	ord := make([]int, n)
	for i := range ord {
		ord[i] = i
	}
	sort.Slice(ord, func(x, y int) bool { return e[ord[x]] < e[ord[y]] })
	ends := make([]int64, n)
	for i, c := range ord {
		ends[i] = e[c]
	}
	best := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		c := ord[i-1]
		// Count calls among the first i-1 ending no later than this start (half-open intervals).
		p := sort.Search(i-1, func(m int) bool { return ends[m] > s[c] })
		best[i] = max(best[i-1], best[p]+v[c])
	}
	fmt.Println(best[n])
}
